callGraph.callee:
chartData.map((item: any) => {
        // PostgREST 관계 조인 결과(tracks)를 어플리케이션 타입에 맞게 매핑
        const rawTrack = item.tracks
        const rawAlbum = rawTrack?.albums
        const rawArtist = rawAlbum?.artists

        return {
          id: item.id,
          period_type: item.period_type,
          period_date: item.period_date,
          track_id: item.track_id,
          rank: item.rank,
          play_count: item.play_count,
          rank_change: item.rank_change,
          track: rawTrack ? {
            ...rawTrack,
            album: rawAlbum ? {
              ...rawAlbum,
              artist: rawArtist
            } : undefined
          } : undefined
        }
      }).filter

chartData.map((item: any) => {
      const rawTrack = item.tracks
      const rawAlbum = rawTrack?.albums
      const rawArtist = rawAlbum?.artists

      return rawTrack ? {
        ...rawTrack,
        rank: item.rank,
        album: rawAlbum ? {
          ...rawAlbum,
          artist: rawArtist
        } : undefined
      } : null
    }).filter

[...customPlaylists].sort((a: any, b: any) => {
      const aVal = a.exposure_order;
      const bVal = b.exposure_order;

      const aHasOrder = aVal !== null && aVal !== undefined && aVal !== '';
      const bHasOrder = bVal !== null && bVal !== undefined && bVal !== '';

      if (aHasOrder && bHasOrder) {
        return Number(aVal) - Number(bVal);
      }
      if (aHasOrder) return -1;
      if (bHasOrder) return 1;

      const aTime = a.created_at ? new Date(a.created_at).getTime() : 0;
      const bTime = b.created_at ? new Date(b.created_at).getTime() : 0;
      return bTime - aTime;
    }).map

